    "authType": "apiSecretServiceAuth",
    "apiSecretServiceAuthConfiguration": {
     "apiSecretRegistrationId": "REPLACE_WITH_API_KEY_REGISTRATION_ID"
    }
   },
   "apiSpecificationFile": "kb-openapi.json",
   "commands": [
    {
