      "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
      "contentVersion": "1.0.0.0",
      "parameters": {
        "$connections": {
          "defaultValue": {},
          "type": "Object"
        },
        "$authentication": {
          "defaultValue": {},
          "type": "SecureObject"
        },
        "PmoMailbox (contoso_PmoMailbox)": {
          "defaultValue": "pmo@contoso.example",
          "type": "String",
          "metadata": {
            "schemaName": "contoso_PmoMailbox"
          }
        }
      },
      "triggers": {
        "Weekdays_at_7": {
          "type": "Recurrence",
          "recurrence": {
            "frequency": "Week",
            "interval": 1,
            "schedule": {
              "weekDays": [
                "Monday",
                "Tuesday",
                "Wednesday",
                "Thursday",
                "Friday"
              ],
              "hours": [
                "7"
              ],
              "minutes": [
                0
              ]
            },
            "timeZone": "W. Europe Standard Time"
          }
        }
      },
      "actions": {
        "Get_overdue": {
          "type": "OpenApiConnection",
