              "apiId": "/providers/Microsoft.PowerApps/apis/shared_sharepointonline"
            },
            "parameters": {
              "dataset": "https://contoso.sharepoint.example/sites/Projects",
              "table": "Project Tasks",
              "$filter": "@concat('Status ne ''Completed'' and DueDate lt ''', formatDateTime(utcNow(), 'yyyy-MM-dd'), '''')",
              "$orderby": "DueDate asc",
              "$top": 500
            },
            "authentication": "@parameters('$authentication')"
          },
          "runAfter": {},
          "runtimeConfiguration": {
            "paginationPolicy": {
              "minimumItemCount": 2000
            }
          }
        },
        "If_any_overdue": {
          "type": "If",
          "runAfter": {
            "Get_overdue": [
              "Succeeded"
            ]
          },
          "expression": {
            "greater": [
              "@length(body('Get_overdue')?['value'])",
              0
            ]
          },
          "actions": {
            "Owner_emails": {
              "type": "Select",
              "runAfter": {},
              "inputs": {
                "from": "@body('Get_overdue')?['value']",
