                      "emailMessage/Subject": "@concat('You have ', length(body('Tasks_of_owner')), ' overdue tasks')",
                      "emailMessage/Body": "@concat('<p>These tasks are past their due date:</p>', body('Task_table'), '<p>Please complete them or move the due date.</p>')",
                      "emailMessage/Importance": "Normal"
                    },
                    "authentication": "@parameters('$authentication')"
                  },
                  "runAfter": {
                    "Task_table": [
                      "Succeeded"
                    ]
                  }
                }
              }
            },
            "Manager_summary": {
              "type": "OpenApiConnection",
              "inputs": {
                "host": {
                  "connectionName": "shared_office365",
                  "operationId": "SendEmailV2",
                  "apiId": "/providers/Microsoft.PowerApps/apis/shared_office365"
                },
                "parameters": {
                  "emailMessage/To": "@parameters('PmoMailbox (contoso_PmoMailbox)')",
                  "emailMessage/Subject": "@concat('Overdue tasks: ', length(body('Get_overdue')?['value']), ' across ', length(outputs('Unique_owners')), ' people')",
                  "emailMessage/Body": "@concat('<p>', length(body('Get_overdue')?['value']), ' tasks are overdue. Digests were sent to ', length(outputs('Unique_owners')), ' owners.</p>')",
                  "emailMessage/Importance": "Normal"
                },
                "authentication": "@parameters('$authentication')"
              },
              "runAfter": {
                "For_each_owner": [
                  "Succeeded"
                ]
              }
            }
          },
          "else": {
            "actions": {
              "Nothing_to_report": {
                "type": "Terminate",
                "runAfter": {},
