  "type": "AdaptiveCard",
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "version": "1.5",
  "msteams": {
    "width": "Full"
  },
  "refresh": {
    "action": {
      "type": "Action.Execute",
      "verb": "refreshApproval",
      "title": "Refresh",
      "data": {
        "requestId": "REQ-1042"
      }
    },
    "userIds": [
      "8:orgid:11111111-2222-3333-4444-555555555555"
    ]
  },
  "body": [
    {
      "type": "TextBlock",
      "text": "Purchase request REQ-1042",
      "wrap": true,
      "size": "Large",
      "weight": "Bolder"
    },
    {
      "type": "TextBlock",
      "text": "Waiting for your decision",
      "wrap": true,
      "isSubtle": true,
      "spacing": "None"
    },
    {
      "type": "FactSet",
      "facts": [
        {
          "title": "Requester",
          "value": "Alex Contoso"
        },
        {
          "title": "Item",
          "value": "Surface Laptop 5, 2 units"
        },
        {
          "title": "Amount",
          "value": "EUR 3,980.00"
        },
        {
          "title": "Cost center",
          "value": "CC-2210"
        }
      ]
    },
    {
      "type": "Input.Text",
      "id": "comment",
      "label": "Comment",
      "placeholder": "Add a reason (required when rejecting)",
      "isMultiline": true,
      "maxLength": 500
    }
  ],
  "actions": [
    {
      "type": "Action.Execute",
      "title": "Approve",
      "verb": "approve",
      "style": "positive",
      "data": {
        "requestId": "REQ-1042",
        "decision": "approved"
      }
    },
    {
      "type": "Action.Execute",
      "title": "Reject",
      "verb": "reject",
      "style": "destructive",
      "data": {
        "requestId": "REQ-1042",
        "decision": "rejected"
