      }
     }
    }
   }
  }
 },
 "definitions": {
  "WorkOrder": {
   "type": "object",
   "properties": {
    "id": {
     "type": "string",
     "description": "Work order number."
    },
    "assetId": {
     "type": "string",
     "description": "Asset or machine ID."
    },
    "status": {
     "type": "string",
     "description": "Open, InProgress or Closed."
    },
    "summary": {
     "type": "string",
     "description": "Short description of the job."
    },
    "createdOn": {
     "type": "string",
     "description": "Creation date, ISO 8601."
    }
   }
  },
  "DefectDraft": {
   "type": "object",
   "required": [
    "assetId",
    "description"
   ],
   "properties": {
    "assetId": {
     "type": "string",
     "description": "Asset or machine ID."
    },
    "description": {
     "type": "string",
     "description": "What was observed, in plain words."
    },
